import numpy as np, torch, model
net=model.load(); w=torch.tensor(np.load('contrast_c3_out_act_k12.npy')); b=-8.0345
N=4096; rng=np.random.default_rng(2)
z=torch.tensor(rng.standard_normal((N,2)).astype(np.float32)); c=torch.tensor(rng.random(N).astype(np.float32))
@torch.no_grad()
def dec(delta=None, klo=0, khi=13, thr=0.0):
    x=z.clone(); fires=torch.zeros(N,dtype=torch.bool)
    for k in range(20):
        t=torch.full((N,),1-k/20)
        v,a=net.velocity(x,t,c,("out_act",),count=False)
        if delta is not None and klo<=k<khi:
            f=(a["out_act"]@w+b)>thr; fires|=f
            v=v+f[:,None].float()*delta
        x=x-v/20
    return x,fires
def lab(x):
    an=torch.atan2(x[:,1],x[:,0])*180/np.pi; return (an>125)|(an<-147)
x0,_=dec()
bad=lab(x0); print('bad',bad.float().mean().item())
def ev(x,f):
    nd=torch.cdist(x,x0).min(1).values
    sb=lab(x)
    q=[round(sb[bad&(c>=lo)&(c<lo+.25)].float().mean().item(),2) for lo in [0,.25,.5,.75]]
    return dict(fall=round((bad.float().mean()-sb.float().mean()).item(),3), still=round(sb[bad].float().mean().item(),3),q=q,
      newbad=round(sb[~bad].float().mean().item(),4), moved=round(((x-x0).norm(dim=1)>0.3)[~bad].float().mean().item(),4),
      off=round((nd>0.25).float().mean().item(),4), fo=round(f[~bad].float().mean().item(),3))
for ang in [6,7,0]:
  for mag in [4,8,16]:
    for (lo,hi) in [(0,13),(0,8),(4,13)]:
      th=ang*np.pi/4; dvec=-mag*torch.tensor([np.cos(th),np.sin(th)],dtype=torch.float32)
      x,f=dec(dvec,lo,hi); print(ang,mag,lo,hi,ev(x,f))
